<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { API_BASE } from '../api'
const props = defineProps({ code: String, name: String, market: String })
const loading = ref(true); const error = ref(''); const stock = ref(null); const market = ref(null); let timer
const taskId = item => item?.task_id || item?.accepted?.[0]?.task_id
async function status(id) { const reply = await fetch(`${API_BASE}/api/ai-analysis/status/${id}/`, { credentials: 'include' }); const data = await reply.json(); if (!reply.ok) throw new Error(data.error || '任务查询失败'); return data }
async function begin() { try { const reply = await fetch(`${API_BASE}/api/ai-analysis/`, { method:'POST', credentials:'include', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ code:props.code, name:props.name, market:props.market }) }); const data = await reply.json(); if (!reply.ok) throw new Error(data.error || '无法提交分析'); stock.value = { taskId: taskId(data.stock_task), status:'pending' }; market.value = { taskId: taskId(data.market_task), status:'pending', warning:data.market_error }; timer = window.setInterval(refresh, 2500); await refresh() } catch (cause) { error.value = cause.message } finally { loading.value = false } }
async function refresh() { try { for (const item of [stock.value, market.value]) if (item?.taskId && !['completed','failed','cancelled'].includes(item.status)) Object.assign(item, await status(item.taskId)) } catch (cause) { error.value = cause.message; clearInterval(timer) } }
onMounted(begin); onBeforeUnmount(() => clearInterval(timer))
</script>
<template><main class="ai-page"><header><button @click="$emit('back')">← 返回行情</button><div><small>AI RESEARCH · daily_stock_analysis</small><h1>{{name}} <span>{{code}}</span></h1></div></header><p class="notice">AI 结论仅供研究参考，不构成投资建议。当前开发阶段不扣除 AI 豆。</p><p v-if="loading" class="loading">正在提交个股与大盘分析任务…</p><p v-if="error" class="error">{{error}}</p><section v-for="item in [{title:'个股 AI 分析',value:stock},{title:'所属大盘复盘',value:market}]" :key="item.title" class="report"><h2>{{item.title}} <em>{{item.value?.status || '等待中'}}</em></h2><p v-if="item.value?.warning">{{item.value.warning}}</p><p v-if="item.value?.message">{{item.value.message}} {{item.value.progress ?? 0}}%</p><pre v-if="item.value?.result?.report">{{JSON.stringify(item.value.result.report,null,2)}}</pre><pre v-else-if="item.value?.market_review_report">{{item.value.market_review_report}}</pre><p v-else>分析引擎正在处理数据与报告，请保持此页面开启。</p></section></main></template>
<style scoped>.ai-page{min-height:100vh;padding:32px max(5vw,24px);background:#09111b;color:#e5edf4}.ai-page header{display:flex;gap:22px;align-items:center}.ai-page button{border:1px solid #375166;background:#10202e;color:#bcd1df;padding:8px 12px}.ai-page small{color:#59d2af}.ai-page h1{margin:4px 0;font-size:27px}.ai-page h1 span{color:#7894a9;font:14px 'DM Mono'}.notice,.loading{color:#91a5b5}.error{padding:10px;border:1px solid #7c3238;color:#ffabb1}.report{max-width:980px;margin:20px 0;padding:20px;border:1px solid #293d50;background:#0d1722}.report h2{margin:0;font-size:17px}.report em{color:#5dd3b0;font:12px 'DM Mono'}.report p{color:#a2b4c1;font-size:13px}.report pre{overflow:auto;padding:14px;background:#081019;color:#d8e6ee;white-space:pre-wrap;font:12px/1.6 'DM Mono'}</style>
